<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
$app=new Nshir\App(); $db=$app->db(); $user=$app->user();
$path=trim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/','/');
function e(?string $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function layout(string $title,string $body,?array $user):void{ ?>
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title><?=e($title)?> | نشر</title><meta name="description" content="نشر - إعلانات مبوبة عربية بسيطة وسريعة"><link rel="stylesheet" href="/assets/app.css"></head>
<body><header class="top"><div class="wrap"><a class="logo" href="/"><b>ن</b>شر</a><nav class="nav"><a class="btn hide-sm" href="/browse">تصفح</a><?php if($user):?><a class="btn" href="/profile"><?=e($user['name'])?></a><?php else:?><a class="btn" href="/login">دخول</a><a class="btn primary" href="/register">تسجيل</a><?php endif;?></nav></div></header><?=$body?></body></html><?php }
function children(PDO $db,string $table,?int $parent):array{$sql="SELECT id,name,slug FROM $table WHERE ".($parent===null?'parent_id IS NULL':'parent_id=?')." AND is_active=1 ORDER BY sort_order,name";$q=$db->prepare($sql);$q->execute($parent===null?[]:[$parent]);return$q->fetchAll();}
function isLeaf(PDO $db,int $id):bool{$q=$db->prepare('SELECT 1 FROM categories WHERE parent_id=? AND is_active=1 LIMIT 1');$q->execute([$id]);return!$q->fetchColumn();}

if($path==='register' && $_SERVER['REQUEST_METHOD']==='POST'){
 $app->verifyCsrf(); $email=mb_strtolower(trim($_POST['email']??''));$name=trim($_POST['name']??'');$pass=(string)($_POST['password']??'');
 if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($name)<2||strlen($pass)<8){http_response_code(422);exit('تحقق من البريد والاسم وكلمة المرور (8 خانات على الأقل).');}
 $country=(int)($_POST['country_id']??0);$city=(int)($_POST['city_id']??0);$area=(int)($_POST['area_id']??0);$token=bin2hex(random_bytes(32));
 $q=$db->prepare('INSERT INTO users(email,name,password_hash,country_id,city_id,area_id,registration_ip,verify_token_hash) VALUES(?,?,?,?,?,?,INET6_ATON(?),?)');
 $q->execute([$email,$name,password_hash($pass,PASSWORD_DEFAULT),$country,$city?:null,$area?:null,$app->clientIp(),hash('sha256',$token)]);
 http_response_code(201);exit('تم إنشاء الحساب. يلزم تفعيل البريد قبل النشر.');
}
if($path==='register'){
 $countries=children($db,'locations',null);ob_start();?><main class="wrap hero"><h1>حساب جديد</h1><p class="muted">بريدك واسمك وكلمة مرور فقط، ثم حدد موقعك مرة واحدة.</p><form class="panel" method="post"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><div class="field"><label>البريد</label><input name="email" type="email" required></div><div class="field"><label>الاسم</label><input name="name" required maxlength="80"></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" minlength="8" required></div><div class="field"><label>الدولة</label><select name="country_id" required><?php foreach($countries as$c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><p class="muted">المدينة والمحافظة تُستكمل من صفحة الموقع بعد إنشاء الحساب.</p><button class="btn primary">إنشاء الحساب</button></form></main><?php layout('تسجيل',ob_get_clean(),$user);exit;
}
if(str_starts_with($path,'category/')){
 $id=(int)substr($path,9);$kids=children($db,'categories',$id);$q=$db->prepare('SELECT id,name FROM categories WHERE id=? AND is_active=1');$q->execute([$id]);$cat=$q->fetch();if(!$cat){http_response_code(404);exit('غير موجود');}
 ob_start();?><main class="wrap hero"><div class="crumbs"><a href="/">الرئيسية</a> / <?=e($cat['name'])?></div><h1><?=e($cat['name'])?></h1><?php if($kids):?><div class="chips"><?php foreach($kids as$k):?><a class="chip" href="/category/<?=$k['id']?>"><?=e($k['name'])?></a><?php endforeach;?></div><?php else:?><p class="muted">وصلت لآخر تصنيف. يمكنك الآن نشر إعلان هنا.</p><?php endif;?></main><?php if(!$kids):?><a class="btn primary publish" href="/publish?category=<?=$id?>">＋ نشر إعلان</a><?php endif;layout($cat['name'],ob_get_clean(),$user);exit;
}
if($path==='publish'){
 if(!$user){header('Location:/login');exit;} $cid=(int)($_GET['category']??$_POST['category_id']??0);if(!$cid||!isLeaf($db,$cid)){header('Location:/');exit;}
 if($_SERVER['REQUEST_METHOD']==='POST'){ $app->verifyCsrf();$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$price=($_POST['price']??'')!==''?(float)$_POST['price']:null;if(mb_strlen($title)<3||mb_strlen($body)<3){http_response_code(422);exit('العنوان والمحتوى مطلوبان.');}
  $q=$db->prepare('INSERT INTO ads(user_id,category_id,country_id,city_id,area_id,title,slug,body,price,publish_ip) VALUES(?,?,?,?,?,?,?,?,?,INET6_ATON(?))');$q->execute([$user['id'],$cid,$user['country_id'],$user['city_id'],$user['area_id'],$title,$app->slug($title),$body,$price,$app->clientIp()]);$id=(int)$db->lastInsertId();header("Location:/ad/$id");exit;}
 ob_start();?><main class="wrap hero"><h1>نشر إعلان</h1><p class="muted">الموقع من بروفايلك والتصنيف محدد مسبقًا.</p><form class="panel" method="post" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><input type="hidden" name="category_id" value="<?=$cid?>"><div class="field"><label>العنوان</label><input name="title" maxlength="160" required></div><div class="field"><label>المحتوى</label><textarea name="body" required></textarea></div><div class="field"><label>السعر</label><input name="price" type="number" min="0" step=".01"></div><div class="field"><label>الصور</label><input name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple></div><button class="btn primary">نشر الآن</button></form></main><?php layout('نشر إعلان',ob_get_clean(),$user);exit;
}
$cats=children($db,'categories',null);$countries=children($db,'locations',null);$ads=$db->query("SELECT a.id,a.title,a.price,a.currency,a.created_at,l.name location_name FROM ads a JOIN locations l ON l.id=a.country_id WHERE a.status='published' ORDER BY a.created_at DESC LIMIT 24")->fetchAll();
ob_start();?><main class="wrap"><section class="hero"><h1>انشر وابحث ببساطة</h1><p class="muted">اختر الدولة أو القسم أو الاثنين معًا.</p><div class="filters"><?php foreach($countries as$l):?><a class="chip" href="/location/<?=$l['id']?>"><?=e($l['name'])?></a><?php endforeach;?></div><div class="chips"><?php foreach($cats as$c):?><a class="chip" href="/category/<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div></section><div class="section-title"><h2>أحدث الإعلانات</h2><div><button class="btn" onclick="document.getElementById('ads').className='grid'">كروت</button> <button class="btn" onclick="document.getElementById('ads').className='list'">قائمة</button></div></div><section id="ads" class="grid"><?php if(!$ads):?><div class="empty">لا توجد إعلانات بعد.</div><?php endif;foreach($ads as$a):?><article class="ad"><a href="/ad/<?=$a['id']?>"><div class="photo">صورة الإعلان</div><div class="info"><?php if($a['price']!==null):?><div class="price"><?=number_format((float)$a['price'])?> ر.س</div><?php endif;?><div class="title"><?=e($a['title'])?></div><div class="meta"><?=e($a['location_name'])?></div></div></a></article><?php endforeach;?></section></main><?php layout('إعلانات مبوبة',ob_get_clean(),$user);
